function* inner() {
  yield 'a';
  yield 'b';
}
function* outer() {
  yield 'start';
  yield___ inner();
  yield 'end';
}
console.log([...outer()].join(','));

L3.canonical:
function* evens() {
  yield 2;
  yield 4;
}
function* odds() {
  yield 1;
  yield 3;
}
function* combined() {
  yield* evens();
  yield* odds();
}
console.log([...combined()].join('-'));
